$cfg=TestSupport::config();$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/contacts-'.$cfg['database'];mkdir($root,0700);foreach(['media','web','sessions']as$dir)mkdir($root.'/'.$dir,0700);
file_put_contents($root.'/private.key',random_bytes(32));chmod($root.'/private.key',0600);putenv('KH_NATIVE_PRIVATE_KEY_FILE='.$root.'/private.key');
$access=new Access($db,'admin');$service=new Subscribers($db,$access);$club=$access->club();$checks=0;$server=null;
