try{
 $rows=[];
 for($i=0;$i<17;$i++)$rows[]=$service->recordWrittenConsent('recipient'.$i.'@example.invalid',sprintf('Kontakt %03d',$i),['events','news'],'Own synthetic signed consent '.$i);
 $foreign=(new Subscribers($db,new Access($db,'outsider')))->recordWrittenConsent('foreign@example.invalid','Private foreign recipient',['news'],'Own foreign synthetic original');
