 $check(SubscriberCatalogue::page($db,$access,array_replace($state,['query'=>'%_!']))['total']===1,'SQL wildcards remain literal human search');
 $check(SubscriberCatalogue::page($db,$access,array_replace($state,['query'=>'Private foreign']))['total']===0,'foreign originals never enter search');
