 foreach([0,'01',[],1.1,1000001]as$v)$deny(fn()=>SubscriberSelection::number($v),'ambiguous page rejected: '.get_debug_type($v));
 $selection=[$rows[0]['id']=>1,$rows[6]['id']=>1];
 $post=['selected'=>$selection,'visible'=>[$rows[0]['id']=>1,$rows[1]['id']=>1],'choice'=>[$rows[1]['id']],'contact_query'=>'human search','contact_page'=>'2','contact_browse'=>'next','reason'=>'human reason'];
 $parsed=SubscriberSelection::state($post,true);
 $check($parsed['selected']===SubscriberSelection::versions([$rows[1]['id']=>1,$rows[6]['id']=>1])&&$parsed['page']===3&&$parsed['reason']==='human reason','browsing retains off-page choices and human reason while applying only shown checkboxes');
 $post['selected'][$rows[1]['id']]=1;$post['visible'][$rows[1]['id']]=2;
