 $deny(fn()=>SubscriberSelection::versions(array_fill_keys(array_map(static fn($i)=>str_pad(dechex($i),32,'0',STR_PAD_LEFT),range(1,101)),1)),'one hundred is the explicit atomic selection bound');
 $original=$service->get($rows[0]['id']);
 $saved=$service->updateProfile($original['id'],1,'Human changed name',['events']);
 $check($saved['version']===2&&$saved['name']==='Human changed name'&&$saved['purposes']===['events'],'name and reduced topics update in one original version');
 foreach(['email','status','consent_evidence','confirmed_at','unsubscribed_at','created_at']as$key)$check($saved[$key]===$original[$key],'profile preserves exact consent original: '.$key);
 $check($service->updateProfile($saved['id'],2,$saved['name'],['events'])===$saved,'unchanged profile makes no artificial revision');
 $deny(fn()=>$service->updateProfile($saved['id'],1,'Stale human text',['events']),'stale tab cannot overwrite current profile');
 $deny(fn()=>$service->updateProfile($saved['id'],2,'Human text',['events','news']),'editing cannot expand consent');
 $deny(fn()=>$service->updateProfile($saved['id'],2,'Human text',[]),'empty topics require explicit unsubscribe');
 $pendingSaved=$service->updateProfile($pending['id'],1,'Human pending name',['events']);
 $check($pendingSaved['status']==='pending'&&$pendingSaved['confirmed_at']===null,'profile editing cannot confirm pending consent');
 $manager=new Manager($db,$access,$root.'/media','own-contact-csrf');
 $edit=['csrf'=>'own-contact-csrf','operation'=>'newsletter-profile','id'=>$saved['id'],'version'=>'2','name'=>'Human from form','purposes'=>['events'],'contact_focus'=>$saved['id']];
 $result=$manager->action('newsletter',$edit,[]);
 $check($result['section']==='recipients'&&$result['compose_state']['contacts']['focus']===$saved['id']&&$service->get($saved['id'])['name']==='Human from form','real form action returns the exact recipient workspace');
 $deny(fn()=>$manager->action('newsletter',array_replace($edit,['csrf'=>'forged']),[]),'profile edit requires current CSRF');
 $deny(fn()=>$manager->action('press',$edit,[]),'profile form cannot cross modules');
 $restored=NewsletterContacts::restore($edit);
 $check($restored['profile']['version']===2&&$restored['profile']['name']==='Human from form','error restoration keeps the submitted version and human name');
 $_GET=['section'=>'recipients'];$html=$manager->main('newsletter','',PHP_INT_MAX,['contacts'=>$restored]);
 $dom=new DOMDocument();@$dom->loadHTML('<?xml encoding="UTF-8">'.$html,LIBXML_NONET);$xp=new DOMXPath($dom);
 $check($xp->query('//input[@name="version" and @value="2"]')->length===1&&$xp->query('//input[@name="email"]')->length===1,'shown correction never substitutes a fresh concurrency version or editable recipient email');
 $check($xp->query('//*[@class="newsletter-contact"]')->length===6,'actual populated manager stays at six recipient cards');
 $before=ownOriginalDatabaseHash($db,['khn_newsletter_subscribers','khn_newsletter_consent_events','khn_newsletter_tokens']);
 $deny(fn()=>$service->unsubscribeSelected([$rows[1]['id']=>1,$rows[2]['id']=>99],'Human reason',true),'one stale selection rejects the whole group');
 $check(ownOriginalDatabaseHash($db,['khn_newsletter_subscribers','khn_newsletter_consent_events','khn_newsletter_tokens'])===$before,'rejected group leaves every selected original and token exact');
 $outbox=new Kulturhus\Native\Delivery\Outbox($db,SecretBox::fromFile($root.'/private.key'));
 $queued=$outbox->enqueue($club,'campaign','own-before-abmeldung',['subscriber'=>$rows[1]['id'],'to'=>$rows[1]['email'],'audience'=>'events','subject'=>'Own synthetic original','text'=>'Do not deliver after revocation'],gmdate('Y-m-d H:i:s'),$access);
 $deny(fn()=>$service->unsubscribeSelected([$rows[1]['id']=>1],'Human reason',false),'bulk unsubscribe needs explicit human confirmation');
 $deny(fn()=>$service->unsubscribeSelected([$rows[1]['id']=>1],'',true),'unsubscribe needs human reason');
 $deny(fn()=>$service->unsubscribeSelected([$rows[1]['id']=>1,$foreign['id']=>1],'Human reason',true),'foreign selected row rejects the whole group');
 $check($service->unsubscribeSelected([$rows[1]['id']=>1,$rows[2]['id']=>1,$pending['id']=>2],'Human opt-out request',true)===3,'one atomic group unsubscribes confirmed and pending own originals');
 $calls=0;$jobs=$outbox->run(static function()use(&$calls){$calls++;return 'unexpected';},10,['campaign'],$club);
 $check($calls===0&&count($jobs)===1&&$jobs[0]['id']===$queued&&$jobs[0]['status']==='cancelled','a previously queued actual worker job is cancelled without invoking any transport');
 $check(!$service->confirm($pendingToken),'old pending confirmation cannot reactivate an unsubscribed original');
 $unsub=$service->get($rows[1]['id']);
 $check($unsub['email']===$rows[1]['email']&&$unsub['consent_evidence']===$rows[1]['consent_evidence']&&$unsub['confirmed_at']===$rows[1]['confirmed_at']&&$unsub['status']==='unsubscribed','unsubscribe keeps the original address and prior consent proof');
 $check($service->unsubscribeSelected([$unsub['id']=>2],'No duplicate state',true)===0,'an already unsubscribed original produces no duplicate event');
 $check($service->updateProfile($unsub['id'],2,'Human after unsubscribe',['events'])['status']==='unsubscribed','profile cannot reactivate an unsubscribed recipient');
 $check(!in_array($unsub['id'],array_column($service->eligible('events'),'id'),true),'revoked recipient immediately leaves new campaign selection');
 for($i=0;$i<9;$i++){$r=$service->get($rows[3]['id']);$service->updateProfile($r['id'],$r['version'],'History human '.$i,['events','news']);}
 $history=$service->historyPage($rows[3]['id']);$older=$service->historyPage($rows[3]['id'],2);
 $check($history['total']===10&&count($history['rows'])===6&&count($older['rows'])===4,'complete consent history remains reachable in six-row pages');
 $deny(fn()=>(new Subscribers($db,new Access($db,'reader')))->updateProfile($rows[4]['id'],1,'Unauthorized',['events']),'read-only role cannot edit recipient');
 Db::run($db,'DELETE FROM native_grants WHERE actor_id=? AND module=? AND capability=?',['admin','newsletter','manage']);
 $deny(fn()=>$service->unsubscribeSelected([$rows[4]['id']=>1],'Revoked administration',true),'existing service honors fresh administration revocation');
 Db::run($db,'INSERT INTO native_grants VALUES(?,?,?)',['admin','newsletter','manage']);
 $check((new Subscribers($db,new Access($db,'outsider')))->get($foreign['id'])===$foreign,'foreign original remains byte-identical');
 if($browser){
  Kulturhus\Native\Integration\Schema::install($db);Kulturhus\Native\Chat\Schema::install($db);Kulturhus\Native\Auth\Schema::install($db);
  Db::run($db,"INSERT INTO clubs(id,name) VALUES('contacts-browser','Own contacts browser')");Db::run($db,"INSERT INTO actors(id,club_id,role,is_superuser) VALUES('contacts-browser-admin','contacts-browser','member',1)");
  $bridge=new Kulturhus\Native\Integration\ManagerBridge($db,'contacts-browser-admin','native',static fn()=>null);$browserAccess=$bridge->access();$browserClub=$browserAccess->club();
  $browserService=new Subscribers($db,$browserAccess);$browserRows=[];
  for($i=0;$i<24;$i++)$browserRows[]=$browserService->recordWrittenConsent('browser'.$i.'@example.invalid',sprintf('Browser contact %03d',$i),['events','news'],'Own browser original signed consent');
  Db::run($db,'INSERT INTO khn_newsletter_subscribers(club_id,id,email,name,status,purposes,consent_evidence,version,confirmed_at,unsubscribed_at,created_at,updated_at) SELECT ?,id,email,name,status,purposes,consent_evidence,version,confirmed_at,unsubscribed_at,created_at,updated_at FROM khn_newsletter_subscribers WHERE club_id=?',[$club,$browserClub]);
  Db::run($db,'INSERT INTO khn_newsletter_consent_events(id,club_id,subscriber_id,action,evidence,actor_id,created_at) SELECT LOWER(REPLACE(UUID(),\'-\',\'\')),?,subscriber_id,action,evidence,actor_id,created_at FROM khn_newsletter_consent_events WHERE club_id=?',[$club,$browserClub]);
  file_put_contents($root.'/auth.key',random_bytes(32));chmod($root.'/auth.key',0600);mkdir($root.'/manager-sessions',0700);putenv('KH_NATIVE_AUTH_KEY_FILE='.$root.'/auth.key');
  $auth=Kulturhus\Native\Auth\Runtime::service($db);$invite=$auth->createInvitation($browserAccess,Kulturhus\Native\Integration\ManagerBridge::actorKey('contacts-browser-admin','contacts-browser'),'contacts-browser@example.invalid');$auth->acceptInvitation($invite['token'],'Own recipient browser password 2026!');$token=$auth->passwordLogin('contacts-browser@example.invalid','Own recipient browser password 2026!','own-contacts-browser')['session_token'];
  $socket=stream_socket_server('tcp://127.0.0.1:0',$errno,$error);$port=(int)substr(strrchr(stream_socket_get_name($socket,false),':'),1);fclose($socket);
  $data=$root.'/browser.json';file_put_contents($data,json_encode(['root'=>$root,'origin'=>'http://127.0.0.1:'.$port,'token'=>$token,'actor'=>$browserAccess->user()['id'],'manager_actor'=>'contacts-browser-admin','native_first'=>$rows[4]['id'],'integrated_first'=>$browserRows[0]['id']],JSON_THROW_ON_ERROR));chmod($data,0600);putenv('DVM_PRESS_RECIPIENTS_FIXTURE='.$data);
  $server=proc_open([...TestSupport::phpCommand(),'-S','127.0.0.1:'.$port,'-t',$root.'/web',__DIR__.'/support/press-recipients-router.php'],[0=>['pipe','r'],1=>['file',$root.'/server.log','a'],2=>['file',$root.'/server.log','a']],$pipes,dirname(__DIR__,2));if(!is_resource($server))throw new RuntimeException('Owned contacts server required.');fclose($pipes[0]);
  $ready=false;for($i=0;$i<100;$i++){$socket=@fsockopen('127.0.0.1',$port,$errno,$error,.1);if($socket){fclose($socket);$ready=true;break;}usleep(50000);}if(!$ready)throw new RuntimeException('Contacts server unavailable.');
  $node=proc_open(['node',__DIR__.'/newsletter-contacts-browser.mjs'],[0=>STDIN,1=>STDOUT,2=>STDERR],$pipes,dirname(__DIR__,2));if(!is_resource($node)||proc_close($node)!==0)throw new RuntimeException('Actual contacts browser failed.');
 }
 echo json_encode(['suite'=>'native-newsletter-contacts','checks'=>$checks,'live_transport'=>false],JSON_THROW_ON_ERROR)."\n";
}finally{if(is_resource($server)){proc_terminate($server);proc_close($server);}unset($_GET);}
